 "content": "def transform(grid):
    """Copy a patterned rectangular frame's interior into same-size hollow frames.

    Blank outlined rectangles of other sizes are removed; the patterned source
    is retained. The outline color is preserved and the source's nonzero
    interior mask is recolored to each destination's outline color.
    """
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    frames = []
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, _ in cells)
        r1 = max(r for r, _ in cells)
        c0 = min(c for _, c in cells)
        c1 = max(c for _, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        if not all(grid[r0][c] == color and grid[r1][c] == color
                   for c in range(c0, c1 + 1)):
            continue
        if not all(grid[r][c0] == color and grid[r][c1] == color
                   for r in range(r0, r1 + 1)):
            continue
        interior = [[grid[r][c] != 0 for c in range(c0 + 1, c1)]
                    for r in range(r0 + 1, r1)]
        patterned = any(any(row) for row in interior)
        frames.append({"color": color, "r0": r0, "r1": r1,
                       "c0": c0, "c1": c1, "patterned": patterned,
                       "mask": interior})

    sources = [f for f in frames if f["patterned"]]
    if not sources:
        return out
    source = max(sources, key=lambda f: sum(sum(row) for row in f["mask"]))
    source_h = source["r1"] - source["r0"] + 1
    source_w = source["c1"] - source["c0"] + 1

    for frame in frames:
        if frame is source or frame["patterned"]:
            continue
        r0, r1, c0, c1 = frame["r0"], frame["r1"], frame["c0"], frame["c1"]
        if r1 - r0 + 1 == source_h and c1 - c0 + 1 == source_w:
            color = frame["color"]
            for rr, row in enumerate(source["mask"]):
                for cc, marked in enumerate(row):
                    out[r0 + 1 + rr][c0 + 1 + cc] = color if marked else 0
        else:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r][c] = 0
    return out


